    if ((this.registers[rs] >>> 0) === (this.registers[rt] >>> 0)) {
      this.pc = (this.pc - 4 + (offset << 2)) >>> 0; // Execute branch to delay slot
    }
    // Nullify delay slot handling is implicit in our VM design
  }

  bnel(rs, rt, offset) {
    // Branch on Not Equal Likely - branch if rs != rt, nullify delay slot if not taken
    if ((this.registers[rs] >>> 0) !== (this.registers[rt] >>> 0)) {
      this.pc = (this.pc - 4 + (offset << 2)) >>> 0; // Execute branch to delay slot
