    // Branch on Greater Than Zero Likely - branch if rs > 0, nullify delay slot if not taken
    if ((this.registers[rs] | 0) > 0) {
      this.pc = (this.pc - 4 + (offset << 2)) >>> 0; // Execute branch to delay slot
    }
